"""CARLA-lazy engineering controller for the nearest-view response comparison.

The two diagnostic constructions share approach geometry and target speed. The
response switch changes only the brake decision when through traffic occupies
the conflict interval. An original capture must establish the observed state.
"""

from __future__ import annotations

import math


KINDS = {
    "nearest_view_response", "nearest_view_uninterrupted",
    "marked_stop_line_response", "marked_stop_line_uninterrupted",
    "near_side_marked_crosswalk_response", "near_side_marked_crosswalk_uninterrupted",
    "near_side_sidewalk_derived_crosswalk_response",
    "near_side_sidewalk_derived_crosswalk_uninterrupted",
    "approaching_phase_probe", "later_history_probe", "nearest_view_stopped",
}


def _finite(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError(f"{name} must be finite")
    return float(value)


def control(kind: str, observation: dict, *, target_speed_mps: float = 4.0) -> dict:
    if kind not in KINDS:
        raise ValueError("unknown exact construction")
    speed = _finite(observation["ego_speed_mps"], "ego_speed_mps")
    distance = _finite(observation["distance_to_view_point_m"], "distance_to_view_point_m")
    target = _finite(target_speed_mps, "target_speed_mps")
    if speed < 0 or target <= 0 or distance < -20:
        raise ValueError("invalid engineering geometry or speed")
    occupied = observation.get("through_vehicle_in_conflict_interval")
    if not isinstance(occupied, bool):
        raise ValueError("through-vehicle conflict observation required")
    if observation.get("yield_sign_governs_approach") is not True:
        raise ValueError("governing yield sign observation required")
    if observation.get("viewpoint_source_verified") is not True:
        raise ValueError("source-verified viewpoint required")
    near_view = distance <= 8.0
    response = near_view and ((kind.endswith("_response") and occupied) or
                              kind == "nearest_view_stopped")
    if response:
        return {"throttle": 0.0, "brake": min(1.0, 0.35 + speed / 6.0),
                "steer": 0.0, "engineering_state": "yield_hold"}
    error = target - speed
    return {"throttle": min(0.45, max(0.0, error * 0.12)),
            "brake": min(0.4, max(0.0, -error * 0.12)),
            "steer": 0.0, "engineering_state": "approach_or_cross"}

"""Lazy CARLA scene adapter for the reviewed C158208 nearest-view pair.

The site packet supplies surveyed actor transforms and camera extrinsics. This
adapter reads actual spawned bodies, a world raycast, and sensor image bytes.
It refuses missing source observations instead of filling them from the plan.
"""
from __future__ import annotations

import math
import queue
import hashlib

from camera_sources import CAMERAS, DIMENSIONS


def _finite(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError(f"{name} must be finite")
    return float(value)


def _pose(carla, data, name):
    if not isinstance(data, dict):
        raise ValueError(f"{name} reviewed pose missing")
    location = data.get("location")
    rotation = data.get("rotation")
    if not isinstance(location, dict) or not isinstance(rotation, dict):
        raise ValueError(f"{name} reviewed location/rotation missing")
    return carla.Transform(
        carla.Location(**{key: _finite(location[key], f"{name} {key}")
                          for key in ("x", "y", "z")}),
        carla.Rotation(**{key: _finite(rotation[key], f"{name} {key}")
                          for key in ("pitch", "yaw", "roll")}))


def validate_native_scene_spec(scene, geometry=None):
    """Check reviewed scene fields before constructing or owning Native actors."""
    if not isinstance(scene, dict):
        raise ValueError("reviewed Native scene source missing")
    for name in ("ego", "through_vehicle"):
        actor = scene.get(name)
        if not isinstance(actor, dict) or not isinstance(actor.get("blueprint_id"), str) or not actor["blueprint_id"]:
            raise ValueError(f"reviewed {name} actor source missing")
        _pose_fields(actor.get("transform"), name)
    ego_xy = scene["ego"]["transform"]["location"]
    through_xy = scene["through_vehicle"]["transform"]["location"]
    if math.hypot(ego_xy["x"] - through_xy["x"],
                  ego_xy["y"] - through_xy["y"]) <= 1.0:
        raise ValueError("reviewed Native vehicle spawn poses overlap")
    if geometry is not None:
        for name, axis_name in (("ego", "ego_route_axis_xy"),
                                ("through_vehicle", "through_route_axis_xy")):
            axis = geometry[axis_name]
            yaw = math.radians(scene[name]["transform"]["rotation"]["yaw"])
            if math.cos(yaw) * axis[0] + math.sin(yaw) * axis[1] <= 0.7:
                raise ValueError(f"{name} spawn heading opposes reviewed route direction")
    cameras = scene.get("cameras")
    if not isinstance(cameras, dict) or set(cameras) != set(CAMERAS):
        raise ValueError("four reviewed camera extrinsics required")
    for name in CAMERAS:
        source = cameras[name]
        if not isinstance(source, dict) or source.get("attach_to") not in ("ego", "through_vehicle"):
            raise ValueError(f"{name} reviewed camera parent missing")
        _pose_fields(source.get("transform"), name)
        fov = _finite(source.get("fov_degrees"), f"{name} fov")
        if not 0 < fov < 180:
            raise ValueError(f"{name} reviewed camera fov outside physical range")
    sign_id = scene.get("yield_sign_actor_id")
    landmark_id = scene.get("yield_sign_landmark_id")
    if (sign_id is None) == (landmark_id is None):
        raise ValueError("exactly one reviewed Native yield sign actor or landmark required")
    if sign_id is not None and (isinstance(sign_id, bool) or not isinstance(sign_id, int) or sign_id <= 0):
        raise ValueError("reviewed Native yield sign actor ID required")
    if landmark_id is not None and (not isinstance(landmark_id, str) or not landmark_id):
        raise ValueError("reviewed Native yield sign landmark ID required")


def _pose_fields(data, name):
    if not isinstance(data, dict) or not isinstance(data.get("location"), dict) or not isinstance(data.get("rotation"), dict):
        raise ValueError(f"{name} reviewed location/rotation missing")
    for key in ("x", "y", "z"):
        _finite(data["location"].get(key), f"{name} {key}")
    for key in ("pitch", "yaw", "roll"):
        _finite(data["rotation"].get(key), f"{name} {key}")


def _vertices(actor, name):
    box = actor.bounding_box
    vertices = box.get_world_vertices(actor.get_transform())
    if len(vertices) != 8:
        raise ValueError(f"{name} original bounding box must have eight vertices")
    points = [[_finite(vertex.x, f"{name} vertex x"),
               _finite(vertex.y, f"{name} vertex y")] for vertex in vertices]
    # Pitch and roll can give more than four distinct XY points. Use the
    # original eight-vertex projection's convex hull rather than assuming a
    # flat vehicle box or silently dropping corner extrema.
    from shapely.geometry import MultiPoint, Polygon
    hull = MultiPoint(points).convex_hull
    if not isinstance(hull, Polygon) or hull.area <= 0:
        raise ValueError(f"{name} original body footprint is degenerate")
    return [list(point) for point in list(hull.exterior.coords)[:-1]]


class CarlaSceneAdapter:
    """Run a reviewed scene using injected CARLA classes and original callbacks."""

    def __init__(self, carla):
        self.carla = carla
        self.world = None
        self.ego = None
        self.through = None
        self.sign = None
        self.sign_kind = None
        self.sensor_queues = {}
        self.sensor_actors = {}
        self.site = None

    def configure(self, world, site):
        scene = site.get("native_scene")
        validate_native_scene_spec(scene, site.get("capture_geometry"))
        for name in ("ego", "through_vehicle"):
            _pose(self.carla, scene[name]["transform"], name)
        cameras = scene["cameras"]
        for name in CAMERAS:
            _pose(self.carla, cameras[name]["transform"], name)
        sign_id = scene.get("yield_sign_actor_id")
        landmark_id = scene.get("yield_sign_landmark_id")
        if (sign_id is None) == (landmark_id is None):
            raise ValueError("exactly one reviewed Native yield sign actor or landmark required")
        if sign_id is not None:
            if isinstance(sign_id, bool) or not isinstance(sign_id, int) or sign_id <= 0:
                raise ValueError("reviewed Native yield sign actor ID required")
            self.sign = world.get_actor(sign_id)
            if self.sign is None or "yield" not in self.sign.type_id.lower():
                raise ValueError("reviewed governing yield sign not found in Native world")
            self.sign_kind = "actor"
        else:
            if not isinstance(landmark_id, str) or not landmark_id:
                raise ValueError("reviewed Native yield sign landmark ID required")
            matches = [item for item in world.get_map().get_all_landmarks()
                       if str(item.id) == landmark_id]
            if len(matches) != 1 or str(matches[0].type) not in ("205", "YIELD", "Yield"):
                raise ValueError("reviewed governing yield landmark not found in Native map")
            self.sign = matches[0]
            self.sign_kind = "landmark"
        settings = world.get_settings()
        settings.synchronous_mode = True
        settings.fixed_delta_seconds = .05
        world.apply_settings(settings)
        readback = world.get_settings()
        if readback.synchronous_mode is not True or readback.fixed_delta_seconds != .05:
            raise ValueError("Native 20 Hz synchronous world readback failed")
        self.site = site
        self.world = world

    def spawn(self, world, site):
        if world is not self.world or site is not self.site:
            raise ValueError("Native scene changed after configuration")
        scene = site["native_scene"]
        library = world.get_blueprint_library()
        owned = []
        try:
            for name in ("ego", "through_vehicle"):
                source = scene[name]
                blueprint = library.find(source["blueprint_id"])
                actor = world.spawn_actor(blueprint, _pose(self.carla, source["transform"], name))
                if actor is None:
                    raise ValueError(f"Native {name} spawn failed")
                setattr(self, "ego" if name == "ego" else "through", actor)
                owned.append(actor)
            for name in CAMERAS:
                source = scene["cameras"][name]
                blueprint = library.find("sensor.camera.rgb")
                width, height = DIMENSIONS[name]
                blueprint.set_attribute("image_size_x", str(width))
                blueprint.set_attribute("image_size_y", str(height))
                blueprint.set_attribute("fov", str(_finite(source["fov_degrees"], f"{name} fov")))
                parent = self.ego if source["attach_to"] == "ego" else self.through
                sensor = world.spawn_actor(blueprint, _pose(self.carla, source["transform"], name), attach_to=parent)
                if sensor is None:
                    raise ValueError(f"Native {name} camera spawn failed")
                inbox = queue.Queue(maxsize=2)
                sensor.listen(inbox.put)
                self.sensor_queues[name] = inbox
                self.sensor_actors[name] = sensor
                owned.append(sensor)
            return owned
        except BaseException:
            for actor in reversed(owned):
                self.destroy(actor)
            raise

    def observe(self, world, actors, frame):
        if world is not self.world or self.ego not in actors or self.through not in actors:
            raise ValueError("Native scene owner/actor mismatch")
        ego_body = _vertices(self.ego, "ego")
        through_body = _vertices(self.through, "through")
        ego_transform = self.ego.get_transform()
        through_transform = self.through.get_transform()
        origin = ego_transform.location
        target = through_transform.location
        hits = world.cast_ray(origin, target)
        if hits is None:
            raise ValueError("Native visibility raycast unavailable")
        hit_ids = [getattr(hit, "actor_id", None) for hit in hits]
        occluded = bool(hit_ids and hit_ids[0] != self.through.id)
        images = {}
        raw_image_hashes = {}
        for name in CAMERAS:
            try:
                image = self.sensor_queues[name].get(timeout=2.0)
            except queue.Empty as exc:
                raise ValueError(f"Native {name} camera frame missing") from exc
            if image.frame != frame:
                raise ValueError(f"Native {name} camera frame differs from world tick")
            if abs(image.timestamp - world.get_snapshot().timestamp.elapsed_seconds) > .001:
                raise ValueError(f"Native {name} camera time differs from world tick")
            if image.width != DIMENSIONS[name][0] or image.height != DIMENSIONS[name][1]:
                raise ValueError(f"Native {name} camera dimensions differ")
            # CARLA supplies BGRA. Preserve original pixels by encoding once as PNG.
            from PIL import Image
            from io import BytesIO
            raw_bytes = bytes(image.raw_data)
            if len(raw_bytes) != image.width * image.height * 4 or any(alpha != 255 for alpha in raw_bytes[3::4]):
                raise ValueError(f"Native {name} BGRA source has invalid length or alpha")
            raw_image_hashes[name] = hashlib.sha256(raw_bytes).hexdigest()
            rgb = Image.frombytes("RGBA", (image.width, image.height), raw_bytes, "raw", "BGRA").convert("RGB")
            stream = BytesIO()
            rgb.save(stream, format="PNG")
            images[name] = stream.getvalue()
        velocity = self.ego.get_velocity()
        through_velocity = self.through.get_velocity()
        if self.sign_kind == "actor":
            sign_present = self.world.get_actor(self.sign.id) is not None
        elif self.sign_kind == "landmark":
            sign_present = any(str(item.id) == str(self.sign.id) and
                               str(item.type) in ("205", "YIELD", "Yield")
                               for item in self.world.get_map().get_all_landmarks())
        else:
            raise ValueError("reviewed governing yield sign source unavailable")
        raw = {"frame": frame,
               "time_s": world.get_snapshot().timestamp.elapsed_seconds,
               "ego": {"body_vertices_xy_m": ego_body,
                       "velocity_xy_mps": [_finite(velocity.x, "ego velocity x"),
                                           _finite(velocity.y, "ego velocity y")]},
               "through_vehicle": {"center_xy_m": [through_transform.location.x,
                                                     through_transform.location.y],
                                   "body_vertices_xy_m": through_body,
                                   "velocity_xy_mps": [_finite(through_velocity.x, "through velocity x"),
                                                       _finite(through_velocity.y, "through velocity y")]},
               "visibility_probe": {"source": "native_raycast", "occluded": occluded,
                                    "origin_xy_m": [origin.x, origin.y],
                                    "target_xy_m": [target.x, target.y],
                                    "hit_actor_ids": hit_ids},
               "camera_raw_bgra_sha256": raw_image_hashes,
               "sign_present": sign_present}
        return {"raw_tick": raw, "cameras": images}

    def apply_control(self, actors, command):
        if self.ego not in actors:
            raise ValueError("ego actor not owned")
        self.ego.apply_control(self.carla.VehicleControl(
            throttle=_finite(command["throttle"], "throttle"),
            brake=_finite(command["brake"], "brake"),
            steer=_finite(command["steer"], "steer")))
        through = command.get("through_control")
        if through is not None:
            if self.through not in actors:
                raise ValueError("through vehicle not owned")
            self.through.apply_control(self.carla.VehicleControl(
                throttle=_finite(through["throttle"], "through throttle"),
                brake=_finite(through["brake"], "through brake"),
                steer=_finite(through["steer"], "through steer")))

    def destroy(self, actor):
        if actor in self.sensor_actors.values():
            actor.stop()
        actor.destroy()

"""Record and independently audit four original camera streams for C158208.

The Native owner passes the actual sensor PNG bytes for each world tick.  A
saved-only audit reopens every archive and decodes every image.  Neither path
asserts that the statutory sign or participant is visually legible.
"""

from __future__ import annotations

import hashlib
from io import BytesIO
import json
from pathlib import Path
from zipfile import ZIP_STORED, ZipFile

from PIL import Image

from source_tick_capture import verify_seal
from yield_control import KINDS


CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
ASSIGNMENT = "testing__C158208__NRS-484B-257-1__motor_vehicle_driver"
DIMENSIONS = {"overview": (1920, 1080), "approach": (1280, 720),
              "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


def _sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _decode(data: bytes, dimensions: tuple[int, int]) -> None:
    with Image.open(BytesIO(data)) as image:
        image.verify()
    with Image.open(BytesIO(data)) as image:
        if image.format != "PNG" or image.size != dimensions:
            raise ValueError("original camera PNG format or dimensions differ")
        image.load()


def _verify_raw_bgra_hash(data: bytes, expected: str, name: str) -> None:
    """Prove the archived lossless PNG reconstructs the original opaque BGRA."""
    if not isinstance(expected, str) or len(expected) != 64:
        raise ValueError(f"{name} original BGRA source hash missing")
    with Image.open(BytesIO(data)) as image:
        reconstructed = image.convert("RGBA").tobytes("raw", "BGRA")
    if _sha(reconstructed) != expected:
        raise ValueError(f"{name} original BGRA source hash differs")


def _safe_file(attempt: Path, name: str) -> Path:
    if not isinstance(name, str) or Path(name).name != name or not name:
        raise ValueError("camera source path must be a direct attempt child")
    return attempt / name


def _identity(attempt: Path, diagnostic_fixture: bool) -> tuple[dict, str]:
    path = attempt / "capture-identity.json"
    data = path.read_bytes()
    identity = json.loads(data)
    if identity.get("format") != "c158208-original-capture-identity-v1":
        raise ValueError("original capture identity format differs")
    if identity.get("assignment_id") != ASSIGNMENT or identity.get("case_id") not in {
            ASSIGNMENT + "__" + kind for kind in KINDS}:
        raise ValueError("original capture identity case differs")
    if identity.get("provenance_kind") != ("synthetic_fixture" if diagnostic_fixture else "original_capture"):
        raise ValueError("original capture identity provenance differs")
    if identity.get("original_tick_seal_sha256") != _sha((attempt / "nearest-view-tick-seal.json").read_bytes()):
        raise ValueError("original capture identity tick seal differs")
    return identity, _sha(data)


def write_camera_sources(attempt: Path, frames: list[dict], *,
                         diagnostic_fixture: bool = False) -> dict:
    """Seal synchronized original PNG bytes supplied by four Native sensors.

    Each frame has ``frame``, ``time_s`` and ``cameras`` mapping camera names to
    unmodified PNG bytes.  Existing attempt media is never overwritten.
    """
    attempt = Path(attempt)
    packet = verify_seal(attempt)
    identity, identity_sha = _identity(attempt, diagnostic_fixture)
    samples = packet["samples"]
    raw_rows = [json.loads(line) for line in (attempt / "nearest-view-original-ticks.jsonl").read_text().splitlines()]
    if len(frames) != len(samples) or (not diagnostic_fixture and len(frames) != 900):
        raise ValueError("camera count differs from 900-frame original tick source")
    dimensions = {name: DIMENSIONS[name] if not diagnostic_fixture else (8, 6)
                  for name in CAMERAS}
    manifest_path = attempt / "nearest-view-camera-manifest.json"
    archives = {name: attempt / f"nearest-view-{name}-original-png.zip" for name in CAMERAS}
    if manifest_path.exists() or any(path.exists() for path in archives.values()):
        raise ValueError("original camera attempt already used")
    rows = []
    for frame, sample in zip(frames, samples):
        if frame.get("frame") != sample["frame"] or frame.get("time_s") != sample["time_s"]:
            raise ValueError("camera frame/time differs from original world tick")
        sources = frame.get("cameras")
        if not isinstance(sources, dict) or set(sources) != set(CAMERAS):
            raise ValueError("four original cameras required for every tick")
        row = {"frame": sample["frame"], "time_s": sample["time_s"], "cameras": {}}
        raw_hashes = raw_rows[len(rows)].get("camera_raw_bgra_sha256")
        if not diagnostic_fixture and (not isinstance(raw_hashes, dict) or set(raw_hashes) != set(CAMERAS)):
            raise ValueError("four original BGRA camera hashes required")
        for name in CAMERAS:
            data = sources[name]
            if not isinstance(data, bytes):
                raise ValueError("original camera source must be PNG bytes")
            _decode(data, dimensions[name])
            if isinstance(raw_hashes, dict) and name in raw_hashes:
                _verify_raw_bgra_hash(data, raw_hashes[name], name)
            row["cameras"][name] = _sha(data)
        rows.append(row)
    for name, path in archives.items():
        with ZipFile(path, "x", compression=ZIP_STORED) as archive:
            for frame in frames:
                archive.writestr(f"{frame['frame']:08d}.png", frame["cameras"][name])
    manifest = {"format": "c158208-original-cameras-v1", "fps": 20,
                "case_id": identity["case_id"], "capture_identity_sha256": identity_sha,
                "provenance_kind": "synthetic_fixture" if diagnostic_fixture else "original_capture",
                "tick_seal_sha256": _sha((attempt / "nearest-view-tick-seal.json").read_bytes()),
                "rows": rows,
                "sources": {name: {"path": path.name, "sha256": _sha(path.read_bytes()),
                                   "dimensions": list(dimensions[name])}
                            for name, path in archives.items()}}
    manifest_path.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return manifest


def audit_camera_sources(attempt: Path, *, diagnostic_fixture: bool = False) -> dict:
    """Saved-only full decode and frame/hash join against original sealed ticks."""
    attempt = Path(attempt)
    packet = verify_seal(attempt)
    identity, identity_sha = _identity(attempt, diagnostic_fixture)
    manifest_path = attempt / "nearest-view-camera-manifest.json"
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    if manifest.get("format") != "c158208-original-cameras-v1" or manifest.get("fps") != 20:
        raise ValueError("original camera manifest format/fps differs")
    if manifest.get("provenance_kind") != ("synthetic_fixture" if diagnostic_fixture else "original_capture"):
        raise ValueError("camera provenance differs")
    if manifest.get("tick_seal_sha256") != _sha((attempt / "nearest-view-tick-seal.json").read_bytes()):
        raise ValueError("camera manifest tick seal differs")
    if manifest.get("case_id") != identity["case_id"] or manifest.get("capture_identity_sha256") != identity_sha:
        raise ValueError("camera manifest capture identity differs")
    samples = packet["samples"]
    raw_rows = [json.loads(line) for line in (attempt / "nearest-view-original-ticks.jsonl").read_text().splitlines()]
    rows = manifest.get("rows")
    if not isinstance(rows, list) or len(rows) != len(samples) or (not diagnostic_fixture and len(rows) != 900):
        raise ValueError("camera count differs from 900-frame original tick source")
    sources = manifest.get("sources")
    if not isinstance(sources, dict) or set(sources) != set(CAMERAS):
        raise ValueError("four original camera archives required")
    for row, sample in zip(rows, samples):
        if row.get("frame") != sample["frame"] or row.get("time_s") != sample["time_s"]:
            raise ValueError("saved camera row differs from original world tick")
        if not isinstance(row.get("cameras"), dict) or set(row["cameras"]) != set(CAMERAS):
            raise ValueError("saved camera row missing a view")
    for name in CAMERAS:
        source = sources[name]
        path = _safe_file(attempt, source.get("path"))
        if source.get("sha256") != _sha(path.read_bytes()):
            raise ValueError(f"{name} original archive hash differs")
        dimensions = DIMENSIONS[name] if not diagnostic_fixture else (8, 6)
        if source.get("dimensions") != list(dimensions):
            raise ValueError(f"{name} original dimensions differ")
        expected_members = [f"{sample['frame']:08d}.png" for sample in samples]
        with ZipFile(path) as archive:
            if archive.namelist() != expected_members:
                raise ValueError(f"{name} original camera frame map differs")
            for index, (member, row) in enumerate(zip(expected_members, rows)):
                data = archive.read(member)
                if _sha(data) != row["cameras"][name]:
                    raise ValueError(f"{name} original camera pixel hash differs")
                _decode(data, dimensions)
                raw_hashes = raw_rows[index].get("camera_raw_bgra_sha256")
                if not diagnostic_fixture and (not isinstance(raw_hashes, dict) or name not in raw_hashes):
                    raise ValueError(f"{name} original BGRA source hash missing")
                if isinstance(raw_hashes, dict) and name in raw_hashes:
                    _verify_raw_bgra_hash(data, raw_hashes[name], name)
    return {"format": "c158208-saved-camera-audit-v1", "frame_count": len(rows),
            "decoded_images": len(rows) * len(CAMERAS),
            "camera_manifest_sha256": _sha(manifest_path.read_bytes()),
            "physical_acceptance": False, "legal_status": "unresolved"}

"""Saved-source measurements for the assigned yield-sign nearest-view branch.

Inputs are original observation packets. This module does not decide legal
applicability, immediate hazard, or right-of-way compliance.
"""

from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path


def _number(value, label):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError(f"{label} must be a finite number")
    return float(value)


def measure(packet: dict) -> dict:
    context = packet["reviewed_context"]
    for name in ("yield_sign_governs_approach", "no_marked_stop_line", "no_near_side_crosswalk",
                 "no_sidewalk_derived_crosswalk", "through_highway_confirmed", "no_officer_control",
                 "no_signal_control", "viewpoint_reviewed"):
        if context.get(name) is not True:
            raise ValueError(f"reviewed context missing {name}")
    samples = packet["samples"]
    if not isinstance(samples, list) or len(samples) < 3:
        raise ValueError("at least three original samples required")
    previous_time = -math.inf
    first_view = None
    crossing = None
    minimum_approach_speed = math.inf
    participant_history = []
    for index, sample in enumerate(samples):
        t = _number(sample["time_s"], "time_s")
        if t <= previous_time:
            raise ValueError("sample times must increase strictly")
        previous_time = t
        speed = _number(sample["ego_speed_mps"], "ego_speed_mps")
        if speed < 0:
            raise ValueError("speed cannot be negative")
        station = _number(sample["ego_front_station_m"], "ego_front_station_m")
        through_station = _number(sample["through_center_station_m"], "through_center_station_m")
        view = sample.get("through_traffic_visible")
        if not isinstance(view, bool):
            raise ValueError("visibility must be an original boolean observation")
        if first_view is None and view:
            first_view = {"index": index, "time_s": t, "ego_front_station_m": station}
        if crossing is None:
            minimum_approach_speed = min(minimum_approach_speed, speed)
            if sample.get("intersection_entry") is True:
                crossing = {"index": index, "time_s": t, "ego_front_station_m": station}
        if not isinstance(sample.get("through_vehicle_within_intersection"), bool):
            raise ValueError("participant occupancy must be observed at every sample")
        participant_history.append({"time_s": t, "through_center_station_m": through_station,
                                    "within_intersection": sample["through_vehicle_within_intersection"]})
    if first_view is None or crossing is None or first_view["index"] >= crossing["index"]:
        raise ValueError("first view must precede intersection entry")
    if samples[0]["through_traffic_visible"]:
        raise ValueError("nearest-view fallback needs a witnessed no-view approach")
    if not any(row["within_intersection"] for row in participant_history[crossing["index"]:]):
        raise ValueError("retain an occupied-through-highway interval during crossing")
    return {
        "kind": "nearest-view-saved-measurement",
        "first_view": first_view,
        "intersection_entry": crossing,
        "minimum_approach_speed_mps": minimum_approach_speed,
        "through_center_station_at_view_m": participant_history[first_view["index"]]["through_center_station_m"],
        "through_vehicle_history": participant_history,
        "sample_count": len(samples),
        "legal_status": "unresolved",
    }


def measure_file(source: Path, output: Path) -> dict:
    raw = source.read_bytes()
    packet = json.loads(raw)
    result = measure(packet)
    result["source"] = {"path": str(source), "sha256": hashlib.sha256(raw).hexdigest()}
    output.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return result


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("source", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    measure_file(args.source, args.output)

